export const requestId='req-stage13-16';
export const weather={version:1,schema:'weather_state',request_id:requestId,weather_kind:'clear',temperature_band:'cool',precipitation:'none',wind:'weak',visibility_weather_modifier:'none',ground_state:'dry',weather_source:'regional_rule',source_trace:[{source_id:'weather'}]};
export const historical={version:1,schema:'historical_frame',request_id:requestId,calendar:{season:'spring'},clock:{time_of_day:'day',light_profile:'daylight'}};
export const selected={version:1,schema:'selected_start_node',request_id:requestId,selected:{selected_scale_level:'G4',selected_place_template_id:'place-template-1',selected_g4_type_id:'yard'},selected_node_chain:{g1_node_id:'g1',g2_node_id:'g2',g3_node_id:'g3',g4_node_id:'g4'}};
export const allowed={version:1,schema:'allowed_g5_template_set',selected_g4_type_id:'yard',allowed_g5_templates:[{template_id:'tpl-1',g4_type_id:'yard',allowed_anchor_types:['entry','center','side'],status:'active'}]};
export const player={version:1,schema:'player_character_game_profile',request_id:requestId,player_character_id:'pc-1',character_id:'pc-1',inventory:[]};
