export function makeStage13Input(){return {version:1,schema:s13.STAGE13_INPUT_SCHEMA,request_id:requestId,normalized_request:{version:1},historical_frame:structuredClone(historical),weather_state:structuredClone(weather),regional_context_package:{version:1,schema:'regional_context_package'},selected_start_node:structuredClone(selected),start_place_audit:structuredClone(startAudit),player_character:structuredClone(player),player_character_audit:structuredClone(playerAudit),npc_candidate_set:structuredClone(npcCandidates),item_profile_candidate_set:structuredClone(itemCandidates),allowed_g5_template_set:structuredClone(allowed),materialization_policy:s13.normalizeStage13MaterializationPolicy({})};}
export function makeG5Draft(overrides={}){return {version:1,schema:s13.STAGE13_OUTPUT_SCHEMA,request_id:requestId,materialization_status:'materialized',frame:{weather_state:structuredClone(weather)},parent_location:{g1_node_id:'g1',g2_node_id:'g2',g3_node_id:'g3',g4_node_id:'g4',place_template_id:'place-template-1'},g5_minilocations:[{g5_minilocation_id:'mini-1',parent_g4_node_id:'g4'}],g5_anchors:[
{anchor_id:'a1',minilocation_id:'mini-1',parent_g4_node_id:'g4',template_id:'tpl-1',anchor_type:'entry',supports:{can_hold_npc:true,can_hold_item:true,can_hold_container:true,npc_capacity:2,item_capacity:3,container_capacity:2},visibility:{visibility_default:'visible'},access:{access_state:'open'}},
{anchor_id:'a2',minilocation_id:'mini-1',parent_g4_node_id:'g4',template_id:'tpl-1',anchor_type:'center',supports:{can_hold_npc:true,can_hold_item:true},visibility:{visibility_default:'visible'},access:{access_state:'open'}},
{anchor_id:'a3',minilocation_id:'mini-1',parent_g4_node_id:'g4',template_id:'tpl-1',anchor_type:'side',supports:{can_hold_item:true},visibility:{visibility_default:'visible_on_inspection'},access:{access_state:'open'}}],g5_edges:[{edge_id:'e1',from_anchor_id:'a1',to_anchor_id:'a2'},{edge_id:'e2',from_anchor_id:'a2',to_anchor_id:'a3'}],player_start_position:{location_id:'g4',minilocation_id:'mini-1',anchor_id:'a1'},visibility_model:{model:'line_of_sight'},access_model:{model:'physical_access'},npc_materialization_slots:[],item_materialization_slots:[],unmaterialized_possible_details:[],downstream_constraints:{},source_trace:[{source_id:'g4'}],audit_self_check:{pass:true,concerns:[],evidence:[{kind:'self'}]},...overrides};}
export function makeStage14Input(){const draft=makeG5Draft();return {version:1,schema:s14.STAGE14_INPUT_SCHEMA,request_id:requestId,historical_frame:structuredClone(historical),selected_start_node:structuredClone(selected),start_place_audit:structuredClone(startAudit),player_character:structuredClone(player),player_character_audit:structuredClone(playerAudit),allowed_g5_template_set:structuredClone(allowed),g5_scene_graph_draft:draft,g5_scene_code_precheck:s13.buildStage13G5CodePrecheck(draft,makeStage13Input()),npc_candidate_set:structuredClone(npcCandidates),item_profile_candidate_set:structuredClone(itemCandidates),audit_policy:s14.normalizeStage14AuditPolicy({})};}
export function makeStage14Audit(){return {version:1,schema:s14.STAGE14_OUTPUT_SCHEMA,request_id:requestId,pass:true,checks:Object.fromEntries(s14.STAGE14_REQUIRED_CHECKS.map(k=>[k,{pass:true,evidence:[{kind:'check'}]}])),concerns:[],evidence:[{kind:'audit'}],repair_route:null,commit_permission:{can_commit_g5_scene_graph:true,can_continue_to_npc_placement:true,can_continue_to_item_placement:true,can_continue_to_visible_context:false}};}
export function makeStage15Input(){return {version:1,schema:s15.STAGE15_INPUT_SCHEMA,request_id:requestId,historical_frame:structuredClone(historical),selected_start_node:structuredClone(selected),start_place_audit:structuredClone(startAudit),player_character:structuredClone(player),player_character_audit:structuredClone(playerAudit),g5_scene_graph:makeG5Draft(),g5_scene_audit:makeStage14Audit(),npc_candidate_set:structuredClone(npcCandidates),item_profile_candidate_set:structuredClone(itemCandidates),npc_placement_policy:s15.normalizeStage15NpcPlacementPolicy({})};}
export function makeStage15Draft(overrides={}){return {version:1,schema:s15.STAGE15_DRAFT_SCHEMA,request_id:requestId,placement_status:'empty_allowed',parent_scene:{g4_node_id:'g4',selected_place_template_id:'place-template-1'},empty_scene_reason:'No NPC is causally required.',npc_instances:[],npc_anchor_bindings:[],npc_visibility_state:[],npc_attention_and_witness_state:[],npc_schedule_state:[],source_trace:[{source_id:'npc-pool'}],audit_self_check:{pass:true,concerns:[],evidence:[{kind:'self'}]},downstream_constraints:{},...overrides};}
export function makeStage15Audit(){return {version:1,schema:s15.STAGE15_AUDIT_SCHEMA,request_id:requestId,pass:true,concerns:[],evidence:[{kind:'audit'}],repair_route:null,commit_permission:{can_commit_npc_instances:true,can_continue_to_item_placement:true,can_continue_to_visible_context:false}};}
export function makeStage16Input(){return {version:1,schema:s16.STAGE16_INPUT_SCHEMA,request_id:requestId,historical_frame:structuredClone(historical),selected_start_node:structuredClone(selected),start_place_audit:structuredClone(startAudit),player_character:structuredClone(player),player_character_audit:structuredClone(playerAudit),g5_scene_graph:makeG5Draft(),g5_scene_audit:makeStage14Audit(),initial_npc_placement:makeStage15Draft(),npc_placement_audit:makeStage15Audit(),item_profile_candidate_set:structuredClone(itemCandidates),item_placement_policy:s16.normalizeStage16ItemPlacementPolicy({})};}
export function makeStage16Draft(overrides={}){return {version:1,schema:s16.STAGE16_DRAFT_SCHEMA,request_id:requestId,placement_status:'empty_allowed',parent_scene:{g4_node_id:'g4',selected_place_template_id:'place-template-1'},empty_scene_reason:'No item is causally required.',item_instances:[],container_instances:[],item_anchor_bindings:[],container_anchor_bindings:[],property_bindings:[],visibility_state:[],access_state:[],risk_state:[],rejected_item_placements:[],source_trace:[{source_id:'item-pool'}],downstream_constraints:{},audit_self_check:{pass:true,concerns:[],evidence:[{kind:'self'}]},...overrides};}
export function makeStage16Audit(){const checks=['all_item_candidates_exist','all_container_candidates_exist','all_property_rules_exist','all_anchors_valid','all_holders_valid','causal_basis_valid','visibility_access_property_risk_valid','closed_containers_protected','no_player_inventory_duplicates','no_forbidden_entities_created','source_trace_sufficient'];return {version:1,schema:s16.STAGE16_AUDIT_SCHEMA,request_id:requestId,pass:true,checks:Object.fromEntries(checks.map(k=>[k,true])),concerns:[],evidence:[{kind:'audit'}],repair_route:null,commit_permission:{can_commit_item_instances:true,can_commit_container_instances:true,can_continue_to_time_light_gate:true,can_continue_to_visible_context:false}};}
